	/**  `f64`, cf. [`ItemDto::price`]. */
	team_type: number | null,
	/**  `f64`, cf. [`ItemDto::price`]. */
	difficulty_type: number | null,
	/**  `f64`, cf. [`ItemDto::price`]. */
